  await this.gateway.send(command)
}

export class FanStateStore {
  @State current: FanState = new FanState()
  private gateway: FanGateway
  async sendCommand(command: FanCommand): Promise<void> {
    await this.gateway.send(command)
  }
  async reloadStatus(): Promise<void> {
    this.current = await this.gateway.readCurrent()
  }
}

@Component
export struct CommandReceiptPage {
  @State receipt: string = ''
  build() {
    Column() {
      Text('Command completed')
      Text(this.receipt)
    }
  }
}

@Component
export struct NotePreviewPage {
  @State preview: string = ''
  private drafts: DraftRepository
  async reloadPreview(): Promise<void> {
    this.preview = await this.drafts.readPreview()
  }
  build() {
    Text(this.preview)
  }
}

